my $json = JSON::PP->new->canonical;
require LinkedSpec;
open my $grammar, '<:raw', 'specs/Lispish.spec' or die $!;
my $spec = do {local $/; <$grammar>};
close $grammar or die $!;
my $parser = LinkedSpec::Get(\$spec);
die "Canonical grammar produced no parser\n" unless ref($parser) eq 'CODE';
open my $input, '<:raw', 'docs/audits/lispish-provider-contract-20261025/inputs.json' or die $!;
my $cases = $json->decode(do {local $/; <$input>});
close $input or die $!;
my @result;
for my $case (@$cases) {
    my $source = $case->{source};
    my @forms;
    while (my $form = $parser->(\$source)) {
        push @forms, $form;
        die "Finite fixture exceeded its form envelope\n" if @forms > 32;
    }
    push @result, {id=>$case->{id}, forms=>\@forms, source_after=>$source, pos=>pos($source)};
}
print $json->encode({pid=>0+$$, cases=>\@result}), "\n";

